class Interval
  attr_reader :start, :finish

  def initialize(start, finish)
    raise ArgumentError, "start must be less than or equal to finish" if start > finish
    @start = start
    @finish = finish
  end

  def overlaps?(other)
    return false unless other.is_a?(Interval)
    # Two intervals [s1, f1] and [s2, f2] overlap (share at least one point)
    # if s1 <= f2 and s2 <= f1
    @start <= other.finish && other.start <= @finish
  end

  def to_a
    [@start, @finish]
  end
end
