class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    data = @packer ? @packer.dump(payload) : payload
    @store[key] = { payload: data, stale: stale }
    nil
  end

  def read(key)
    entry = @store[key]
    return nil unless entry
    data = entry[:payload]
    @packer ? @packer.load(data) : data
  end

  def sweep
    @store.delete_if { |key, entry| entry[:stale] }
    self
  end
end
